def _parse_csv_value(value: Any) -> Any:
    """Turn one CSV cell back into its original Python type.

    A faithful port of the ``parse_value`` closure inside
    :func:`spacr.utils.load_settings`, reproduced here rather than imported
    because ``spacr.utils`` pulls torch and cellpose — twenty seconds and a
    CUDA context to read a two-column CSV. :mod:`spacr.validate` reproduces
    ``_get_regex`` for the same reason. Any behaviour change there must be
    mirrored here; the round trip is covered by ``tests/test_cli.py``.

    :param value: raw cell text.
    :returns: bool, int, float, None, list, tuple, dict or str.
    """
    if value is None or value == "":
        return None
    if not isinstance(value, str):
        return value
    if value.strip().lower() == "true":
        return True
    if value.strip().lower() == "false":
        return False
    if value.startswith(("(", "[", "{")):
        try:
            parsed = ast.literal_eval(value)
        except (ValueError, SyntaxError):
            return value
        if isinstance(parsed, dict):
            return {k: _parse_csv_value(v) for k, v in parsed.items()}
        return parsed
    try:
        if "." in value:
            return float(value)
        return int(value)
    except ValueError:
        pass
    return value

def load_settings_file(path: Any) -> Dict[str, Any]:
    """Load a settings file written by the GUI, a pipeline run or a run journal.

    :param path: path to a ``.csv`` or ``.json`` settings file.
    :returns: the settings dict.
    :raises SettingsError: when the path is missing, unreadable or malformed.
        Never a traceback — a cluster job should fail with a sentence.
    """
    if not isinstance(path, str) or not path.strip():
        raise SettingsError("no settings file given; pass --settings <file>.")
    if not os.path.exists(path):
        raise SettingsError(
            f"settings file not found: {path}\n"
            f"  Check the path, and that the share holding it is mounted on this node.")
    if os.path.isdir(path):
        raise SettingsError(
            f"--settings expects a file, but {path} is a folder.\n"
            f"  A run writes its settings to <src>/settings/*.csv — point at one of those.")
    try:
        if path.lower().endswith(".json"):
            return _load_settings_json(path)
        return _load_settings_csv(path)
    except SettingsError:
        raise
    except (OSError, UnicodeDecodeError) as exc:
        raise SettingsError(f"could not read {path}: {exc}") from exc
    except (json.JSONDecodeError, csv.Error) as exc:
        raise SettingsError(f"could not parse {path}: {exc}") from exc

def _settings_json_value(value: Any) -> Any:
    """A settings value as something JSON can hold, or its ``repr``.

    :param value: a settings value.
    :returns: ``None``, a bool, number or string, a list or dict of those,
        or the ``repr`` of anything else.
    """
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, dict):
        return {str(k): _settings_json_value(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_settings_json_value(v) for v in value]
    item = getattr(value, "item", None)
    if callable(item):
        try:
            return _settings_json_value(item())
        except (TypeError, ValueError):
            pass
    return repr(value)

def coerce_value(key: str, text: str, current: Any,
                 expected_types: Mapping[str, Any], app: str = "") -> Any:
    """Coerce a ``--set key=value`` string into the type the setting expects.

    The type comes from :data:`spacr.settings.expected_types` when the key is
    declared there, otherwise from the type of the value the key already holds.
    A value that cannot be coerced is an error rather than a silently-stored
    string: ``cell_mask_dim='4'`` is exactly the bug the settings CSV round trip
    keeps producing, and measure_crop only notices it an hour in.

    :param key: settings key.
    :param text: the raw text after the first ``=``.
    :param current: the value ``key`` holds before the override.
    :param expected_types: :data:`spacr.settings.expected_types`.
    :param app: module key, so a key two pipelines share is read as the module
        being run means it (see :data:`_APP_TYPE_OVERRIDES`).
    :returns: the coerced value.
    :raises SettingsError: when ``text`` is not a legal value for ``key``.
    """
    types = _allowed_types(key, current, expected_types, app)
    stripped = text.strip()
    lowered = stripped.lower()
    allow = (lambda t: True) if not types else (lambda t: t in types)

    if lowered in _NONE_WORDS and (not types or type(None) in types):
        return None

    if key in _PATH_LIST_KEYS:
        from .portable_paths import _parse_path_list

        paths = _parse_path_list(text)
        if all(isinstance(path, str) for path in paths) and paths:
            return paths[0] if len(paths) == 1 else paths

    if stripped.startswith("{") and allow(dict):
        try:
            parsed = ast.literal_eval(stripped)
        except (ValueError, SyntaxError) as exc:
            raise SettingsError(f"--set {key}={text!r} is not a valid dict: {exc}") from exc
        if isinstance(parsed, dict):
            return parsed

    if stripped.startswith(("[", "(")) and (allow(list) or allow(tuple)):
        try:
            parsed = ast.literal_eval(stripped)
        except (ValueError, SyntaxError) as exc:
            raise SettingsError(f"--set {key}={text!r} is not a valid list: {exc}") from exc
        if isinstance(parsed, (list, tuple)):
            return tuple(parsed) if (allow(tuple) and not allow(list)) else list(parsed)

    if allow(bool):
        if lowered in _TRUE_WORDS:
            return True
        if lowered in _FALSE_WORDS:
            return False

    if allow(int):
        try:
            return int(stripped)
        except ValueError:
            try:
                as_float = float(stripped)
            except ValueError:
                as_float = None
            if as_float is not None and as_float.is_integer():
                return int(as_float)

    if allow(float):
        try:
            return float(stripped)
        except ValueError:
            pass

    if (key == "custom_model"
            and lowered in (_TRUE_WORDS | _FALSE_WORDS)):
        raise SettingsError(
            "--set custom_model is a checkpoint path, not a boolean switch; "
            "use custom_model=none for the stock Cellpose model."
        )

    if allow(str):
        return text

    if allow(list) or allow(tuple):
        items = [_literal_scalar(part) for part in stripped.split(",")] if stripped else []
        return tuple(items) if (allow(tuple) and not allow(list)) else items

    raise SettingsError(
        f"--set {key}={text!r} cannot be read as {_type_label(types)}.\n"
        f"  {key} expects {_type_label(types)}; the current value is {current!r}.")

def _parse_setting_value(value: Any) -> Any:
    """Turn one cell of a settings CSV back into the Python value it was.

    ``True``/``False`` (any case), a literal list, tuple or dict (whose
    values are parsed the same way), an int, a float, an empty cell
    (``None``), or the text as written.

    :param value: the cell as pandas read it.
    :returns: the parsed value.
    """
    if pd.isna(value) or value == '':
        return None
    if not isinstance(value, str):
        return value
    if value.strip().lower() == 'true':
        return True
    if value.strip().lower() == 'false':
        return False
    if value.startswith(('(', '[', '{')):
        import ast
        try:
            parsed = ast.literal_eval(value)
            if isinstance(parsed, dict):
                parsed = {k: _parse_setting_value(v) for k, v in parsed.items()}
            return parsed
        except (ValueError, SyntaxError):
            pass
    try:
        if '.' in value:
            return float(value)
        return int(value)
    except ValueError:
        pass
    return value

def _apply_each_setting(self, settings: dict) -> int:
    """Push each key into its widget. Returns how many landed."""
    applied = 0
    for key, val in settings.items():
        w = self._settings_model._widgets.get(key)
        if w is None:
            if self._settings_model.set_hidden_value(key, val):
                from .settings_model import _APP_HIDDEN_KEYS
                if key in _APP_HIDDEN_KEYS.get(self.app_key, set()):
                    applied += 1
            continue
        try:
            self._apply_value(w, val)
            applied += 1
        except Exception:
            pass
    self._settings_model._refresh_contextual_widgets()
    return applied

def collect(self) -> Dict[str, Any]:
    """Read all widgets and return the current settings dict.

    A control still waiting for its category to be opened is read
    without being built; see :meth:`_read_value`.
    """
    for hook in list(self._collect_hooks):
        try:
            hook()
        except Exception:
            LOGGER.debug("a collect hook failed", exc_info=True)
    out: Dict[str, Any] = {}
    for key in self._widgets:
        out[key] = self._canonical(
            key, self._coerce_to_expected_type(key, self._read_value(key)))
    for k, v in self._defaults.items():
        out.setdefault(k, v)
    return self._organelle_slots_worth_keeping(out)

def map_settings_paths(
    value: Any,
    local_root: str,
    remote_root: str,
) -> Any:
    """Recursively map absolute paths below one local root to a remote root.

    Non-path strings and paths outside the configured root are unchanged.
    Mapping keys are intentionally preserved: setting names are not paths.

    :param value: nested settings value whose absolute path strings are mapped.
    :param local_root: local dataset root that mapped paths must lie below.
    :param remote_root: remote dataset root that replaces ``local_root``.
    """
    if isinstance(value, dict):
        return {
            key: map_settings_paths(item, local_root, remote_root)
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [
            map_settings_paths(item, local_root, remote_root)
            for item in value
        ]
    if isinstance(value, tuple):
        return [
            map_settings_paths(item, local_root, remote_root)
            for item in value
        ]
    if isinstance(value, str) and os.path.isabs(os.path.expanduser(value)):
        return _map_path_string(value, local_root, remote_root)
    return value

def submit(
    self, profile: ExecutionProfile, job: RemoteJob, payload: str
) -> None:
    """Start the job through the profile's own submit template.

    :param profile: the execution profile.
    :param job: the job, updated in place.
    :param payload: the settings to upload.
    :raises RemoteExecutionError: if the template cannot be rendered, the
        submission fails, or the id it returned does not validate.
    """
    del payload
    output = _require_ok(
        self.runner(
            _render_template(
                profile.submit_command, self._context(profile, job),
                "Submit command",
            ),
            timeout=120.0,
        ),
        "Cloud/custom submission",
    )
    identifier = ""
    if profile.job_id_pattern:
        match = re.search(profile.job_id_pattern, output)
        if match:
            identifier = (
                match.groupdict().get("id")
                if match.groupdict() else match.group(1)
                if match.groups() else match.group(0)
            )
    else:
        identifier = next(
            (line.strip() for line in output.splitlines() if line.strip()),
            "",
        )
    job.external_id = _safe_external_id(identifier)
    job.log_reference = "custom command"
    job.status = "queued"

def catalogue(include_bundled: bool = True, remote: bool = True,
              catalogue_path: Any = None,
              include_plugins: bool = True,
              block: Optional[bool] = None) -> List[ModelEntry]:
    """Everything the zoo knows about without scanning the user's disks.

    That is: the models bundled with the installed package (whatever
    :func:`spacr.utils.download_models` has put in ``resources/models``), plus
    the declared remote entries — :data:`BUNDLED_REMOTE_MODELS` and, if one is
    configured, the JSON catalogue named by ``catalogue_path`` or the
    :data:`CATALOGUE_ENV_VAR` environment variable.

    Local apart from one thing:
    with ``remote`` on, this also asks :func:`shared_catalogue` for the
    community rows, which is a network call. It works offline either way --
    that fetch never raises -- and it never blocks Qt's GUI thread, which
    :func:`shared_catalogue` enforces for itself.

    :param include_bundled: list the models in the package resources folder.
    :param remote: list declared remote entries.
    :param catalogue_path: a JSON catalogue to add; defaults to
        ``$SPACR_MODEL_CATALOGUE`` when that names a file.
    :param include_plugins: include entries returned by installed spaCR model
        providers. Provider failures are recorded in plugin diagnostics and do
        not hide built-in entries.
    :param block: passed to :func:`shared_catalogue`. ``False`` takes the
        community rows from its cache rather than waiting for the network;
        ``None`` lets that function decide from the thread it is on.
    :returns: bundled entries first, then remote ones already present locally
        are dropped (a downloaded model is listed once, as the local file).
    """
    entries: List[ModelEntry] = []
    if include_bundled:
        root = package_model_root()
        if root.is_dir():
            entries.extend(discover_local(root, max_depth=2))

    entries.extend(stock_cellpose_entries())
    entries.extend(installable_backend_entries())
    entries.extend(_cellpose3_model_entries())
    entries.extend(_prefixed_model_entries())
    if remote:
        entries.extend(bioimageio_entries())
    if remote:
        have = {(e.key, e.name) for e in entries}
        for record in BUNDLED_REMOTE_MODELS:
            entry = _entry_from_mapping(record)
            if (entry.key, entry.name) not in have:
                entries.append(entry)
                have.add((entry.key, entry.name))
        path = catalogue_path or os.environ.get(CATALOGUE_ENV_VAR, "")
        if path and os.path.isfile(str(path)):
            for entry in load_catalogue_file(path):
                if (entry.key, entry.name) not in have:
                    entries.append(entry)
                    have.add((entry.key, entry.name))
        for entry in shared_catalogue(block=block):
            if (entry.key, entry.name) not in have:
                entries.append(entry)
                have.add((entry.key, entry.name))
    entries = [e for e in entries if e.name not in RETIRED_MODEL_NAMES]
    if include_plugins:
        try:
            from .plugins import (
                load_object,
                model_providers,
                record_diagnostic,
            )
            have = {(entry.key, entry.name) for entry in entries}
            for plugin_name, contribution in model_providers():
                try:
                    provider = load_object(contribution.provider)
                    if not callable(provider):
                        raise TypeError(
                            f"{contribution.provider!r} is not callable"
                        )
                    produced = provider()
                    if isinstance(produced, (ModelEntry, Mapping)):
                        produced = (produced,)
                    for item in produced or ():
                        entry = (
                            item if isinstance(item, ModelEntry)
                            else _entry_from_mapping(item)
                        )
                        identity = (entry.key, entry.name)
                        if identity not in have:
                            entries.append(entry)
                            have.add(identity)
                except Exception as exc:
                    record_diagnostic(
                        plugin_name,
                        f"Model provider {contribution.key!r} failed",
                        exc,
                    )
        except Exception:
            LOG.exception("Could not initialise plugin model providers")
    return entries

def _ensure_model_file(requested, *, kinds=(), download=True):
    """Resolve a catalogue checkpoint and fetch missing verified weights.

    Local paths win. Unknown identifiers return None for the caller's
    existing stock-model or missing-path handling. With download=False,
    return the intended cache path without fetching checkpoint bytes.
    A Qt GUI-thread caller must use the model picker for a missing model.
    """
    text = os.fspath(requested).strip() if requested is not None else ""
    if not text:
        return None
    local = Path(text).expanduser()
    if local.is_file():
        return local
    if os.sep in text or text.startswith("~"):
        return None
    entry = next((item for item in catalogue(remote=True)
                  if item.key == text or item.name == text), None)
    if entry is None:
        return None
    if kinds and entry.kind not in kinds:
        raise ModelZooError(
            f"{text!r} is a {entry.kind} model; this operation requires "
            f"one of {', '.join(kinds)}")
    if entry.path and Path(entry.path).is_file():
        return Path(entry.path)
    if not entry.uri:
        return None
    destination = _spacr_home() / "models"
    cached = destination / Path(entry.name).name
    if cached.is_file():
        if entry.sha256 and sha256_file(cached) == entry.sha256.lower():
            return cached
    if entry.sha256 and destination.is_dir():
        for version in sorted(destination.glob(
                f"{cached.stem}_v*{cached.suffix}")):
            if version.is_file() and sha256_file(version) == entry.sha256.lower():
                return version
    if not download:
        return cached
    if _on_the_qt_gui_thread():
        raise ModelUnreadable(
            f"{text!r} is not cached. Download it in Model Zoo, or run "
            f"the operation through spacr-run or Python without a GUI.")
    LOG.info("Downloading requested model %s into %s", entry.key, destination)
    return fetch(entry, destination)

def _real_classifier_bundles(location: str) -> Dict[str, Dict[str, Any]]:
    """Load the classifiers a run names, keyed by object type.

    :param location: one saved classifier, or a folder holding
        ``cell.joblib``, ``nucleus.joblib`` and/or ``pathogen.joblib``.
    :raises ValueError: nothing loadable there.
    """
    import joblib

    location = os.path.expanduser(str(location))
    if not os.path.exists(location):
        from .model_zoo import _ensure_model_file
        downloaded = _ensure_model_file(location, kinds=("classifier",))
        if downloaded is not None:
            location = str(downloaded)
    if os.path.isdir(location):
        paths = [os.path.join(location, f"{kind}.joblib") for kind in _REAL_TYPES]
        paths = [path for path in paths if os.path.isfile(path)]
    elif os.path.isfile(location):
        paths = [location]
    else:
        raise ValueError(f"real_object_classifier not found: {location}")
    bundles = {}
    for path in paths:
        bundle = joblib.load(path)
        if not isinstance(bundle, Mapping) or bundle.get("object_type") not in _REAL_TYPES:
            raise ValueError(f"{path} is not a real / not-real classifier")
        bundles[bundle["object_type"]] = dict(bundle)
    if not bundles:
        raise ValueError(f"no cell, nucleus or pathogen classifier in {location}")
    return bundles

def _zoo_path(key: str, cache: Path) -> Tuple[str, str]:
    """A zoo model's local path and a description to record with results.

    :param key: a zoo key, or a path to a checkpoint.
    :param cache: where a downloaded model is kept.
    :returns: ``(path, 'name sha256')``.
    """
    if Path(str(key)).exists():
        return str(key), f"{Path(str(key)).name}"
    from . import model_zoo as zoo

    entry = zoo.resolve(key, zoo.catalogue())
    path = entry.path if getattr(entry, "path", None) and Path(entry.path).exists() \
        else zoo.fetch(entry, cache)
    return str(path), f"{entry.name} {entry.sha256 or ''}".strip()
